// ELIPS TC-PBR Service Acceptance Monitoring (Service Acceptance > SA Monitoring). Rules: sa-pas-rules.js (window.SAPAS).
// Shows SA generated by SA Approval (sa.js, window.SA_DATA) with the ELIPS snapshot and the PAS interface / feedback data.
// Spec: docs/sa-monitoring-spec.md.
(function () {
  const STORE = 'elips-sam-v1';
  const ST = SAPAS.STATUS, L = SAPAS.LABEL, WBS = SAPAS.WBS;
  const SAS = SA_DATA.SAS;
  const PASACT = { role: 'SYSTEM', name: 'PAS Interface' };
  const OVERDUE_H = 24; // TBD: feedback waiting time before the overdue flag
  const money = n => n == null ? '-' : Number(n).toLocaleString('en-US');
  const kmFmt = n => n == null ? '-' : Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
  const dt = d => d ? fmtDT(new Date(d)) : '-';
  const d10 = d => d ? SA.ymd(new Date(d)) : '';
  const lpCodeOf = name => (SUPPLIERS.find(s => s[0] === name) || [])[1] || '';
  const canView = () => ['PLANNER', 'IELP_ADMIN', 'SUPPLIER'].includes(state.actor.role);
  const canRetry = a => a.role === 'IELP_ADMIN'; // separate authorization (proposed): Retry Interface
  const visible = () => SAS.filter(s => state.actor.role === 'SUPPLIER' ? s.lpCode === lpCodeOf(state.actor.supplier) : true);
  const ST_CLS = { NOT_SENT: 'ns', PROCESSING: 'pr', SENT: 'sn', PR_RECEIVED: 'rr', PO_RECEIVED: 'or', COMPLETED: 'cp', FAILED: 'fl' };
  const badge = p => `<span class="pas ${ST_CLS[p.status]}">${L[p.status]}</span>${SAPAS.overdue(p, new Date(), OVERDUE_H) ? ' <span class="pas od" title="No PAS feedback for more than ' + OVERDUE_H + ' h (TBD)">Overdue</span>' : ''}`;
  const services = d => d.legs.map(() => 'CE'); // TBD: service type per cycle (value 'CE' on the reference screen)
  const wbsOf = d => SAPAS.wbsSplit(d.cost, services(d));

  // ---------- PAS state: restore, or seed the legacy SA for the demo ----------
  const saved = (() => { try { return JSON.parse(localStorage.getItem(STORE) || 'null'); } catch (e) { return null; } })() || { pas: {}, processed: {}, n: 0 };
  const FB = { processed: saved.processed || {}, n: saved.n || 0, last: null };
  const persist = () => {
    try { localStorage.setItem(STORE, JSON.stringify({ pas: Object.fromEntries(SAS.map(s => [s.saNo, { pas: s.pas, pasLog: s.pasLog }])), processed: FB.processed, n: FB.n })); } catch (e) { /* storage not available */ }
    SA_DATA.persist();
  };
  const prNoGen = () => `5000${String(269000 + (++FB.n)).padStart(6, '0')}`;
  const poNoGen = () => `45${String(50288000 + FB.n).padStart(8, '0')}`;
  const store = () => ({ sas: SAS, processed: FB.processed });
  function onPo(h, at) { // PAS PO received: Daily orders of the SA -> SA Approved with PO Number (existing Daily status)
    h.details.forEach(d => { const o = DATA.find(x => x.orderNo === d.orderNo); if (o && o.status === W.ORDER.SA) W.perform(o, 'processPAS', { poNo: h.pas.poNo }, PASACT, at, CTX); });
  }
  const legacy = SAS.filter(s => s.legacy).sort((a, b) => a.approvedAt - b.approvedAt);
  const failSeed = SAS.find(s => s.legacy && s.totalCost > 0 && !s.details.some(d => DATA.find(o => o.orderNo === d.orderNo)?.poNo));
  SAS.forEach(s => {
    const sv = saved.pas[s.saNo];
    if (sv) { s.pas = sv.pas; s.pasLog = sv.pasLog || []; return; }
    s.pas = s.pas || SAPAS.init(); s.pasLog = s.pasLog || [];
    if (!s.legacy) return;
    const i = legacy.indexOf(s), at = new Date(s.approvedAt.getTime() + 3600000);
    const orders = s.details.map(d => DATA.find(o => o.orderNo === d.orderNo)).filter(Boolean);
    const po = orders.length && orders.every(o => o.poNo) ? orders[0].poNo : '';
    if (s === failSeed) { SAPAS.send(s, { at, actor: PASACT, result: 'unavailable', canRetry }); return; }
    SAPAS.send(s, { at, actor: PASACT, result: 'ok', canRetry });
    const fbAt = new Date(at.getTime() + 7200000);
    if (po) SAPAS.applyFeedback(store(), { feedbackId: `SEED-${s.saNo}`, saNo: s.saNo, correlationId: s.pas.correlationId, type: 'PR_PO', prNo: prNoGen(), prDate: d10(fbAt), poNo: po }, { at: fbAt });
    else if (i % 3 === 1) SAPAS.applyFeedback(store(), { feedbackId: `SEED-${s.saNo}`, saNo: s.saNo, correlationId: s.pas.correlationId, type: 'PR', prNo: prNoGen(), prDate: d10(fbAt) }, { at: fbAt });
  });

  // ---------- Screen state ----------
  const today = SA.ymd(new Date());
  const lastMonth = (() => { const d = new Date(); d.setMonth(d.getMonth() - 1, 1); return SA.ymd(d); })();
  const blankF = () => ({ from: lastMonth, to: today, saNo: '', status: '', lp: '', type: '', delNo: '', delDate: '', prNo: '', poNo: '', poEmpty: false });
  const typeOf = s => s.type === 'MONTHLY' ? 'MONTHLY' : 'DELIVERY';
  const TYPE_L = { DELIVERY: 'Delivery', MONTHLY: 'Monthly Truck' };
  const sm = { tab: 'list', f: blankF(), q: '', page: 1, size: 10, hidden: new Set(['elipsPo', 'rate', 'cur']), sim: { saNo: '', act: 'send_ok', msg: '' } };
  const has = (v, q) => String(v || '').toLowerCase().includes(q.trim().toLowerCase());
  function headers() {
    const f = sm.f;
    return visible().filter(s => { const d = d10(s.approvedAt);
      return (!f.from || d >= f.from) && (!f.to || d <= f.to) && (!f.saNo || has(s.saNo, f.saNo)) && (!f.status || s.pas.status === f.status) && (!f.lp || s.lpCode === f.lp) && (!f.type || typeOf(s) === f.type)
        && (!f.prNo || has(s.pas.prNo, f.prNo)) && (!f.poNo || has(s.pas.poNo, f.poNo)) && (!f.poEmpty || !s.pas.poNo)
        && (!f.delNo || s.details.some(x => has(x.orderNo, f.delNo))) && (!f.delDate || s.details.some(x => x.date === f.delDate)); })
      .sort((a, b) => b.approvedAt - a.approvedAt || (a.saNo < b.saNo ? -1 : 1));
  }
  function detailRows() {
    const f = sm.f;
    return headers().flatMap(h => h.details.filter(d => (!f.delNo || has(d.orderNo, f.delNo)) && (!f.delDate || d.date === f.delDate)).map(d => ({ h, d, w: wbsOf(d) })))
      .filter(({ h, d }) => !sm.q || [h.saNo, d.detNo, d.orderNo, d.description, h.lpCode, h.pas.prNo, h.pas.poNo, d.route, h.poNo, L[h.pas.status], TYPE_L[typeOf(h)]].some(v => has(v, sm.q)));
  }
  const hid = k => sm.hidden.has(k) ? ' style="display:none"' : '';
  const COLS = [['type', 'SA Type'], ['detNo', 'SA Det No'], ['delNo', 'Delivery No'], ['delDate', 'Delivery Date'], ['lp', 'Truck Company'], ['prNo', 'PAS PR No'], ['poNo', 'PAS PO No'], ['prDate', 'PAS PR Date'],
    ['ifs', 'Interface Status'], ['route', 'Route Code'], ['ctr', 'Ctr Size'], ['svc', 'Service Type'], ['km', 'Total KM'], ['elipsPo', 'ELIPS PO No'], ['rate', 'Rate / KM'], ['price', 'Price'], ['cur', 'Currency'],
    ['wbsPct', 'WBS % (Percentage)'], ['wbsCost', 'WBS Cost'], ['appr', 'Approval Date']];
  const ctrOf = no => DATA.find(o => o.orderNo === no)?.dtp?.ctrSize || '-';
  const pager = (n) => { const pages = Math.max(1, Math.ceil(n / sm.size)); sm.page = Math.min(sm.page, pages);
    return `<div class="dn-pager"><span class="q-note">Showing ${n ? (sm.page - 1) * sm.size + 1 : 0} to ${Math.min(n, sm.page * sm.size)} of ${n} records</span><span class="spacer"></span>
      <select id="smSize">${[10, 25, 50].map(x => `<option ${x === sm.size ? 'selected' : ''}>${x}</option>`).join('')}</select>
      <button class="btn-light" data-smpg="-1" ${sm.page === 1 ? 'disabled' : ''}>&lsaquo; Prev</button><span class="q-note">Page ${sm.page} / ${pages}</span><button class="btn-light" data-smpg="1" ${sm.page === pages ? 'disabled' : ''}>Next &rsaquo;</button></div>`; };
  const page = arr => arr.slice((sm.page - 1) * sm.size, sm.page * sm.size);

  function listTable() {
    const rows = detailRows(), view = page(rows);
    const sum = { price: rows.reduce((s, r) => s + (r.d.cost || 0), 0), w: Object.fromEntries(WBS.map(k => [k, rows.reduce((s, r) => s + r.w.amt[k], 0)])) };
    return `<div class="table-wrap"><table class="sa-tbl sam-tbl"><thead>
      <tr><th rowspan="2">Options</th><th rowspan="2">SA No</th>${COLS.map(([k, l]) => k === 'svc' ? `<th colspan="5"${hid(k)}>Service Type</th>` : k === 'wbsPct' ? `<th colspan="6"${hid(k)}>WBS Consumption Master (Percentage)</th>` : k === 'wbsCost' ? `<th colspan="6"${hid(k)}>WBS Consumption Master (Cost)</th>` : `<th rowspan="2"${hid(k)}>${l}</th>`).join('')}</tr>
      <tr>${[1, 2, 3, 4, 5].map(n => `<th${hid('svc')}>Cycle ${n}</th>`).join('')}${WBS.map(k => `<th${hid('wbsPct')}>${k}</th>`).join('')}${WBS.map(k => `<th${hid('wbsCost')}>${k}</th>`).join('')}</tr></thead>
      <tbody>${view.map(({ h, d, w }) => `<tr>
        <td><button class="act" data-smdet="${h.saNo}" title="View Detail">&#9776;</button></td><td>${h.saNo}</td>
        <td${hid('type')}><span class="st ${typeOf(h) === 'MONTHLY' ? 'sb' : 'rd'}">${TYPE_L[typeOf(h)]}</span></td>
        <td${hid('detNo')}>${d.detNo || '-'}</td><td${hid('delNo')}>${d.kind === 'MONTHLY' ? `<small>${esc(d.description)}</small>` : d.orderNo}</td><td${hid('delDate')}>${d.kind === 'MONTHLY' ? SA.ymLabel(d.ym) : d.date}</td><td${hid('lp')}>${h.lpCode}</td>
        <td${hid('prNo')}>${h.pas.prNo || '-'}</td><td${hid('poNo')}>${h.pas.poNo || '-'}</td><td${hid('prDate')}>${h.pas.prDate || '-'}</td><td${hid('ifs')}>${badge(h.pas)}</td>
        <td class="left"${hid('route')}>${d.route || '-'}</td><td${hid('ctr')}>${ctrOf(d.orderNo)}</td>
        ${[0, 1, 2, 3, 4].map(i => `<td${hid('svc')}>${services(d)[i] || '-'}</td>`).join('')}
        <td class="num"${hid('km')}>${kmFmt(d.totalKm)}</td><td${hid('elipsPo')}>${d.poNo || '-'}</td><td class="num"${hid('rate')}>${money(d.rate)}</td>
        <td class="num sa-price"${hid('price')}>${money(d.cost)}</td><td${hid('cur')}>${d.currency || '-'}</td>
        ${WBS.map(k => `<td${hid('wbsPct')}>${w.pct[k] ? w.pct[k] + '%' : '-'}</td>`).join('')}${WBS.map(k => `<td class="num"${hid('wbsCost')}>${w.amt[k] ? money(w.amt[k]) : '-'}</td>`).join('')}
        <td${hid('appr')}>${fmtDate(d10(h.approvedAt))}</td></tr>`).join('') || '<tr><td colspan="45" class="empty">No Data Found</td></tr>'}
      ${rows.length ? `<tr class="sam-sum"><td colspan="${2 + ['type', 'detNo', 'delNo', 'delDate', 'lp', 'prNo', 'poNo', 'prDate', 'ifs', 'route', 'ctr'].filter(k => !sm.hidden.has(k)).length + (sm.hidden.has('svc') ? 0 : 5) + ['km', 'elipsPo', 'rate'].filter(k => !sm.hidden.has(k)).length}" class="num"><b>Summary :</b></td>
        <td class="num sa-price"${hid('price')}><b>${money(sum.price)}</b></td><td${hid('cur')}></td><td colspan="6"${hid('wbsPct')} class="num"><b>WBS Cost Summary :</b></td>
        ${WBS.map(k => `<td class="num"${hid('wbsCost')}><b>${money(sum.w[k])}</b></td>`).join('')}<td${hid('appr')}></td></tr>` : ''}</tbody></table></div>${pager(rows.length)}`;
  }
  function groupTable() {
    const hs = headers().filter(h => !sm.q || [h.saNo, h.lpCode, h.lpName, h.pas.prNo, h.pas.poNo, h.poNo, L[h.pas.status], ...h.details.map(d => d.orderNo)].some(v => has(v, sm.q))), view = page(hs);
    const wsum = h => Object.fromEntries(WBS.map(k => [k, h.details.reduce((s, d) => s + wbsOf(d).amt[k], 0)]));
    const tot = { cost: hs.reduce((s, h) => s + (h.totalCost || 0), 0), w: Object.fromEntries(WBS.map(k => [k, hs.reduce((s, h) => s + wsum(h)[k], 0)])) };
    return `<div class="table-wrap"><table class="sa-tbl sam-tbl"><thead>
      <tr><th rowspan="2">Action</th><th rowspan="2">SA Number</th><th rowspan="2">SA Type</th><th rowspan="2">SA Approval Date</th><th rowspan="2">Approved By</th><th rowspan="2">Truck Company</th><th rowspan="2">Delivery Count</th><th rowspan="2">Total KM</th>
        <th rowspan="2">Total Cost</th><th rowspan="2">Currency</th><th colspan="6">WBS Consumption Master (Cost)</th><th rowspan="2">PAS PR Number</th><th rowspan="2">PAS PR Date</th><th rowspan="2">PAS PO Number</th>
        <th rowspan="2">Interface Status</th><th rowspan="2">Feedback</th><th rowspan="2">Last Update</th></tr><tr>${WBS.map(k => `<th>${k}</th>`).join('')}</tr></thead>
      <tbody>${view.map(h => { const w = wsum(h), retry = h.pas.status === ST.FAILED && !h.pas.prNo && !h.pas.poNo;
        return `<tr><td><div class="ta-act"><button class="act" data-smdet="${h.saNo}" title="View Detail">&#9776;</button><button class="act" data-smlog="${h.saNo}" title="View Interface Log">&#128203;</button>
          ${retry ? `<button class="act" data-smretry="${h.saNo}" ${canRetry(state.actor) ? '' : 'disabled'} title="${canRetry(state.actor) ? 'Retry Interface' : 'Retry Interface needs the retry authorization (IELP Admin)'}">&#8635;</button>` : ''}</div></td>
          <td>${h.saNo}${h.legacy ? ' <small class="q-note">legacy</small>' : ''}</td><td><span class="st ${typeOf(h) === 'MONTHLY' ? 'sb' : 'rd'}">${TYPE_L[typeOf(h)]}</span></td><td>${dt(h.approvedAt)}</td><td>${esc(h.approvedBy)}</td><td class="left">${h.lpCode} - ${esc(h.lpName)}</td><td class="num">${typeOf(h) === 'MONTHLY' ? '-' : h.deliveries}</td>
          <td class="num">${kmFmt(h.totalKm)}</td><td class="num sa-price">${money(h.totalCost)}</td><td>${h.currency}</td>${WBS.map(k => `<td class="num">${w[k] ? money(w[k]) : '-'}</td>`).join('')}
          <td>${h.pas.prNo || '-'}</td><td>${h.pas.prDate || '-'}</td><td>${h.pas.poNo || '-'}</td><td>${badge(h.pas)}</td>
          <td>${h.pas.feedbackStatus || '-'}${h.pas.errorCode ? `<small class="sub" title="${esc(h.pas.errorMessage)}">${h.pas.errorCode}</small>` : ''}</td><td>${dt(h.pas.updatedAt || h.approvedAt)}</td></tr>`; }).join('') || '<tr><td colspan="25" class="empty">No Data Found</td></tr>'}
      ${hs.length ? `<tr class="sam-sum"><td colspan="8" class="num"><b>Summary :</b></td><td class="num sa-price"><b>${money(tot.cost)}</b></td><td></td>${WBS.map(k => `<td class="num"><b>${money(tot.w[k])}</b></td>`).join('')}<td colspan="6"></td></tr>` : ''}</tbody></table></div>${pager(hs.length)}`;
  }

  function render() {
    const root = $('samRoot'); if (!root || $('pgSAM').style.display === 'none') return;
    if (!canView()) { root.innerHTML = '<section class="cal-card"><p class="q-note">SA Monitoring is not available for this role.</p></section>'; return; }
    const f = sm.f, all = visible(), cnt = {}; all.forEach(s => { cnt[s.pas.status] = (cnt[s.pas.status] || 0) + 1; });
    const simOn = ['PLANNER', 'IELP_ADMIN'].includes(state.actor.role);
    root.innerHTML = `<section class="cal-card">
      <div class="sam-filter">
        <div><label for="smFrom">SA Date From</label><input type="date" id="smFrom" value="${f.from}"></div>
        <div><label for="smTo">SA Date To</label><input type="date" id="smTo" value="${f.to}"></div>
        <div><label for="smSaNo">SA Number</label><input id="smSaNo" value="${esc(f.saNo)}" placeholder="contains"></div>
        <div><label for="smStatus">Status <span class="req">*</span></label><select id="smStatus"><option value="">All</option>${Object.keys(ST).map(k => `<option value="${k}" ${f.status === k ? 'selected' : ''}>${L[k]}</option>`).join('')}</select></div>
        <div><label for="smLp">Truck Company <span class="req">*</span></label><select id="smLp" ${state.actor.role === 'SUPPLIER' ? 'disabled' : ''}><option value="">All</option>${SUPPLIERS.map(([n, c]) => `<option value="${c}" ${f.lp === c ? 'selected' : ''}>${c} - ${n}</option>`).join('')}</select></div>
        <div><label for="smType">SA Type</label><select id="smType"><option value="">All</option>${Object.entries(TYPE_L).map(([k, l]) => `<option value="${k}" ${f.type === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
        <div><label for="smDelNo">Delivery Number</label><input id="smDelNo" value="${esc(f.delNo)}" placeholder="contains"></div>
        <div><label for="smDelDate">Delivery Date</label><input type="date" id="smDelDate" value="${f.delDate}"></div>
        <div><label for="smPrNo">PAS PR Number</label><input id="smPrNo" value="${esc(f.prNo)}" placeholder="contains"></div>
        <div><label for="smPoNo">PAS PO Number</label><input id="smPoNo" value="${esc(f.poNo)}" placeholder="contains"></div>
        <div class="sam-chk"><label class="form-check"><input type="checkbox" id="smPoEmpty" ${f.poEmpty ? 'checked' : ''}> PAS PO Number empty</label></div>
      </div>
      <div class="sam-btns"><button class="btn-dark" id="smSearch">&#128269; Search</button><button class="btn-light" id="smCancel">&#8635; Cancel</button></div>
    </section>
    <section class="cal-card">
      <div class="sam-chips">${Object.keys(ST).map(k => `<button class="pas ${ST_CLS[k]} ${f.status === k ? 'on' : ''}" data-smchip="${k}">${L[k]} <b>${cnt[k] || 0}</b></button>`).join('')}<span class="q-note">Interface status of ${all.length} SA · click to filter</span></div>
      <div class="sa-tabs"><button data-smtab="list" class="${sm.tab === 'list' ? 'on' : ''}">Service Acceptance List</button><button data-smtab="wbs" class="${sm.tab === 'wbs' ? 'on' : ''}">Service Acceptance List (WBS Group)</button><button data-smtab="inter" class="${sm.tab === 'inter' ? 'on' : ''}">Inter Plant</button></div>
      <div class="sa-bar"><b>${sm.tab === 'wbs' ? 'Service Acceptance List (WBS Group)' : 'Service Acceptance List'}</b><span class="spacer"></span>
        <div class="search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg><input type="text" id="smQ" placeholder="Search" value="${esc(sm.q)}"></div>
        ${sm.tab === 'list' ? `<div class="dd" id="smKolomDd"><button class="btn-blue" id="smKolom">Kolom &#9662;</button><div class="dd-menu">${COLS.map(([k, l]) => `<label><input type="checkbox" data-smcol="${k}" ${sm.hidden.has(k) ? '' : 'checked'}> ${l}</label>`).join('')}</div></div>` : ''}
        <button class="btn-green" id="smExport">&#11015; Export Excel</button></div>
      ${sm.tab === 'list' ? listTable() : sm.tab === 'wbs' ? groupTable() : '<p class="q-note sa-empty">Inter Plant: selection rule not defined yet (TBD, see open questions).</p>'}
    </section>
    ${simOn ? `<details class="cal-card sam-sim" ${sm.sim.open ? 'open' : ''} id="smSimBox"><summary>Demo: PAS interface simulator (mock-up only - in production these events come from the interface batch and PAS)</summary>
      <div class="sam-simrow"><select id="smSimSa">${visible().map(s => `<option ${sm.sim.saNo === s.saNo ? 'selected' : ''}>${s.saNo}</option>`).join('')}</select>
        <select id="smSimAct">${[['send_ok', 'ELIPS -> PAS: send SA (success)'], ['send_unavailable', 'ELIPS -> PAS: PAS unavailable'], ['send_timeout', 'ELIPS -> PAS: timeout'], ['send_rejected', 'ELIPS -> PAS: request rejected'],
          ['fb_pr', 'PAS -> ELIPS: PR feedback'], ['fb_po', 'PAS -> ELIPS: PO feedback'], ['fb_prpo', 'PAS -> ELIPS: PR + PO feedback'], ['fb_dup', 'Resend last feedback (same feedback id)'],
          ['fb_conflict', 'PR feedback with a different PR Number'], ['fb_nodate', 'PR feedback without PR Date'], ['fb_unknown', 'Feedback for unknown SA Number'], ['fb_corr', 'Feedback with wrong Correlation ID'],
          ['fb_prfail', 'PAS error: PR creation failed'], ['fb_pofail', 'PAS error: PO creation failed'], ['fb_db', 'PR feedback, database update fails'], ['batch', 'Interface batch: send all Not Sent']]
          .map(([v, l]) => `<option value="${v}" ${sm.sim.act === v ? 'selected' : ''}>${l}</option>`).join('')}</select>
        <button class="btn-dark" id="smSimRun">Run</button><span class="q-note" id="smSimMsg">${esc(sm.sim.msg)}</span></div></details>` : ''}`;
  }

  // ---------- Detail / log ----------
  function detail(saNo) {
    const h = SAS.find(s => s.saNo === saNo), p = h.pas;
    const sec = (t, src, body) => `<h4 class="sa-h4">${t} <small class="src ${src === 'PAS' ? 'pas-src' : ''}">Source: ${src === 'PAS' ? 'PAS feedback' : src}</small></h4>${body}`;
    const info = arr => `<div class="ta-info">${arr.map(([k, v]) => `<div><b>${k}</b>${v}</div>`).join('')}</div>`;
    showPreview(`SA ${h.saNo}`,
      sec('A. SA Information', 'ELIPS (SA Approval)', info([['SA Number', h.saNo], ['SA Date', fmtDate(d10(h.approvedAt))], ['Approved Date', dt(h.approvedAt)], ['Approved By', esc(h.approvedBy)], ['SA Status', h.status]])) +
      sec('B. Trucking Information', 'ELIPS (SA Approval)', info([['Trucking Company', esc(h.lpName)], ['Trucking Company Code', h.lpCode]])) +
      (typeOf(h) === 'MONTHLY' ? sec('C. Monthly Truck Cost', 'ELIPS snapshot', info([['SA Det No', h.details[0].detNo], ['Description', esc(h.details[0].description)], ['Production Month', SA.ymLabel(h.ym)], ['Service Period', `${h.poFrom} - ${h.poTo}`], ['PR Number (ELIPS)', h.prNo], ['Monthly Cost', `${money(h.totalCost)} ${h.currency}`]])) :
      sec('C. Delivery Information', 'ELIPS snapshot', `<table class="sa-mini"><tr><th>SA Det No</th><th>Delivery Number</th><th>Delivery Date</th><th>Route</th><th>Origin</th><th>Destination</th><th>Total KM</th><th>Rate / KM</th><th>Cost</th></tr>
        ${h.details.map(d => `<tr><td>${d.detNo || '-'}</td><td>${d.orderNo}</td><td>${d.date}</td><td>${d.route || '-'}</td><td>${d.legs[0] ? `${d.legs[0].from} - ${esc(d.legs[0].fromName)}` : '-'}</td>
          <td>${d.legs.length ? `${d.legs[d.legs.length - 1].to} - ${esc(d.legs[d.legs.length - 1].toName)}` : '-'}</td><td class="num">${kmFmt(d.totalKm)}</td><td class="num">${money(d.rate)}</td><td class="num">${money(d.cost)}</td></tr>`).join('')}</table>`)) +
      sec('D. Cost Calculation', 'ELIPS snapshot (not changed by PAS)', info([['ELIPS / Cost Reference PO', h.poNo], ['PO Validity', h.poFrom ? `${h.poFrom} - ${h.poTo}` : '-'], ['PO Rate', typeOf(h) === 'MONTHLY' ? 'Monthly Cost (Fixed)' : [...new Set(h.details.map(d => money(d.rate)))].join(' / ') + ' ' + h.currency + '/km'], ['Total KM', kmFmt(h.totalKm)], ['Calculated Cost', `${money(h.totalCost)} ${h.currency}`], ['Currency', h.currency]])) +
      sec('E. PAS Information', 'PAS', info([['PAS PR Number', p.prNo || '-'], ['PAS PR Date', p.prDate || '-'], ['PAS PO Number', p.poNo || '-'], ['PAS Interface Status', badge(p)]])) +
      sec('F. Integration Information', 'PAS', info([['Interface Date', dt(p.interfaceAt)], ['Correlation ID', p.correlationId || '-'], ['Attempts', p.attempts], ['Last Feedback Date', dt(p.lastFeedbackAt)], ['Feedback Status', p.feedbackStatus || '-'], ['Error Code', p.errorCode || '-'], ['Error Message', esc(p.errorMessage || '-')]])) +
      sec('G. Audit Information', 'ELIPS', info([['Created Date', dt(h.createdAt)], ['Created By', esc(h.approvedBy)], ['Approved Date', dt(h.approvedAt)], ['Approved By', esc(h.approvedBy)], ['Last Updated Date', dt(p.updatedAt || h.approvedAt)]])) +
      logTable(h), '');
    $('preview').querySelector('.pv').classList.add('dn-pv');
  }
  const logTable = h => `<table class="sa-mini"><tr><th>Date-time</th><th>Event</th><th>Actor</th><th>Previous</th><th>New</th><th>Correlation ID</th><th>Error</th></tr>
    ${[...h.audit.map(a => ({ at: a.at, event: a.action, actor: a.by, prev: '-', next: h.legacy ? 'SA Approved' : 'NOT_SENT', correlationId: '', errorCode: '', errorMessage: a.note })), ...h.pasLog]
      .map(e => `<tr><td>${dt(e.at)}</td><td>${e.event}</td><td>${esc(e.actor)}</td><td>${e.prev || '-'}</td><td>${e.next || '-'}</td><td>${e.correlationId || '-'}</td><td>${e.errorCode ? `${e.errorCode}: ${esc(e.errorMessage)}` : esc(e.errorMessage || '')}</td></tr>`).join('')}</table>`;
  function log(saNo) { const h = SAS.find(s => s.saNo === saNo); showPreview(`Interface Log - ${saNo}`, logTable(h), ''); $('preview').querySelector('.pv').classList.add('dn-pv'); }

  // ---------- Simulator / retry ----------
  function runSim() {
    const saNo = $('smSimSa').value, act = $('smSimAct').value, h = SAS.find(s => s.saNo === saNo), at = new Date();
    sm.sim = { saNo, act, open: true, msg: '' };
    let r;
    if (act === 'batch') {
      const list = visible().filter(s => s.pas.status === ST.NOT_SENT);
      list.forEach(s => SAPAS.send(s, { at, actor: PASACT, result: 'ok', canRetry }));
      r = { status: 200, message: `${list.length} SA sent to PAS` };
    } else if (act.startsWith('send_')) r = SAPAS.send(h, { at, actor: PASACT, result: act.slice(5), canRetry });
    else {
      const base = { feedbackId: `FB-${Date.now()}-${++FB.n}`, saNo, correlationId: h.pas.correlationId };
      const fb = {
        fb_pr: { ...base, type: 'PR', prNo: prNoGen(), prDate: today }, fb_po: { ...base, type: 'PO', poNo: poNoGen() }, fb_prpo: { ...base, type: 'PR_PO', prNo: prNoGen(), prDate: today, poNo: poNoGen() },
        fb_dup: FB.last || { ...base, type: 'PR', prNo: prNoGen(), prDate: today }, fb_conflict: { ...base, type: 'PR', prNo: prNoGen(), prDate: today }, fb_nodate: { ...base, type: 'PR', prNo: prNoGen(), prDate: '' },
        fb_unknown: { ...base, saNo: 'ILS/TR/XXX/2611049999', type: 'PR', prNo: prNoGen(), prDate: today }, fb_corr: { ...base, correlationId: 'WRONG-ID', type: 'PR', prNo: prNoGen(), prDate: today },
        fb_prfail: { ...base, type: 'ERROR', errorCode: 'PR_CREATION_FAILED', errorMessage: 'PAS could not create the PR (budget / WBS not valid)' },
        fb_pofail: { ...base, type: 'ERROR', errorCode: 'PO_CREATION_FAILED', errorMessage: 'PAS could not create the PO' }, fb_db: { ...base, type: 'PR', prNo: prNoGen(), prDate: today },
      }[act];
      if (act === 'fb_conflict' && !h.pas.prNo) { r = { status: '-', message: 'Select an SA that already has a PAS PR Number' }; }
      else {
        r = SAPAS.applyFeedback(store(), fb, { at, dbFail: act === 'fb_db' });
        if (act !== 'fb_dup') FB.last = fb;
        if (r.poReceived) onPo(h, at);
      }
    }
    sm.sim.msg = `HTTP ${r.status} · ${r.code || ''} ${r.message}`;
    persist(); render(); window.render?.();
  }
  function retry(saNo) {
    const h = SAS.find(s => s.saNo === saNo);
    const r = SAPAS.send(h, { at: new Date(), actor: state.actor, result: 'ok', canRetry });
    toast(r.message); persist(); render();
  }

  // ---------- Export ----------
  function exportExcel() {
    let aoa;
    if (sm.tab === 'wbs') aoa = [['SA Number', 'SA Type', 'SA Approval Date', 'Approved By', 'Trucking Code', 'Trucking Company', 'Delivery Count', 'Total KM', 'Total Cost', 'Currency', 'PAS PR Number', 'PAS PR Date', 'PAS PO Number', 'Interface Status', 'Feedback', 'Error', 'Last Update'],
      ...headers().map(h => [h.saNo, TYPE_L[typeOf(h)], dt(h.approvedAt), h.approvedBy, h.lpCode, h.lpName, h.deliveries, h.totalKm, h.totalCost, h.currency, h.pas.prNo, h.pas.prDate, h.pas.poNo, L[h.pas.status], h.pas.feedbackStatus, h.pas.errorCode, dt(h.pas.updatedAt || h.approvedAt)])];
    else aoa = [['SA No', 'SA Type', 'SA Det No', 'Delivery No', 'Delivery Date', 'Trucking Code', 'PAS PR No', 'PAS PO No', 'PAS PR Date', 'Interface Status', 'Route Code', 'Total KM', 'ELIPS PO No', 'Rate / KM', 'Price', 'Currency', ...WBS.map(k => `WBS % ${k}`), ...WBS.map(k => `WBS Cost ${k}`), 'Approval Date'],
      ...detailRows().map(({ h, d, w }) => [h.saNo, TYPE_L[typeOf(h)], d.detNo, d.orderNo || d.description, d.date, h.lpCode, h.pas.prNo, h.pas.poNo, h.pas.prDate, L[h.pas.status], d.route, d.totalKm, d.poNo, d.rate, d.cost, d.currency, ...WBS.map(k => w.pct[k]), ...WBS.map(k => w.amt[k]), d10(h.approvedAt)])];
    if (aoa.length < 2) { toast('Tidak ada data untuk diexport'); return; }
    const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(aoa), 'SA Monitoring');
    const n = new Date(); XLSX.writeFile(wb, `SA Monitoring_${SA.ymd(n).replace(/-/g, '')}${pad(n.getHours())}${pad(n.getMinutes())}${pad(n.getSeconds())}.xlsx`);
  }

  // ---------- Events ----------
  const readF = () => Object.assign(sm.f, { from: $('smFrom').value, to: $('smTo').value, saNo: $('smSaNo').value, status: $('smStatus').value, lp: $('smLp').value, type: $('smType').value,
    delNo: $('smDelNo').value, delDate: $('smDelDate').value, prNo: $('smPrNo').value, poNo: $('smPoNo').value, poEmpty: $('smPoEmpty').checked });
  document.addEventListener('click', e => {
    const t = e.target; if (!t.closest('#pgSAM')) return;
    if (t.id === 'smSearch') { readF(); sm.page = 1; render(); }
    if (t.id === 'smCancel') { sm.f = blankF(); sm.q = ''; sm.page = 1; render(); }
    const chip = t.closest('[data-smchip]'); if (chip) { sm.f.status = sm.f.status === chip.dataset.smchip ? '' : chip.dataset.smchip; sm.page = 1; render(); }
    const tab = t.closest('[data-smtab]'); if (tab) { sm.tab = tab.dataset.smtab; sm.page = 1; render(); }
    const pg = t.closest('[data-smpg]'); if (pg && !pg.disabled) { sm.page += +pg.dataset.smpg; render(); }
    const d = t.closest('[data-smdet]'); if (d) detail(d.dataset.smdet);
    const lg = t.closest('[data-smlog]'); if (lg) log(lg.dataset.smlog);
    const rt = t.closest('[data-smretry]'); if (rt && !rt.disabled) retry(rt.dataset.smretry);
    if (t.id === 'smExport') exportExcel();
    if (t.id === 'smSimRun') runSim();
    if (t.id === 'smKolom') { e.stopPropagation(); $('smKolomDd').classList.toggle('open'); }
  });
  document.addEventListener('change', e => {
    const t = e.target; if (!t.closest('#pgSAM')) return;
    if (t.id === 'smSize') { sm.size = +t.value; sm.page = 1; render(); }
    if (t.dataset.smcol) { t.checked ? sm.hidden.delete(t.dataset.smcol) : sm.hidden.add(t.dataset.smcol); render(); $('smKolomDd').classList.add('open'); }
  });
  document.addEventListener('toggle', e => { if (e.target.id === 'smSimBox') sm.sim.open = e.target.open; }, true);
  document.addEventListener('input', e => { if (e.target.id === 'smQ') { sm.q = e.target.value; sm.page = 1; const pos = e.target.selectionStart; render(); $('smQ').focus(); $('smQ').setSelectionRange(pos, pos); } });
  document.addEventListener('actorchange', () => { sm.f.lp = ''; render(); });

  window.samRender = render;
  window.samChanged = () => { persist(); render(); };
  window.SAM = { SAS, FB, runSim, store };
  persist();
  render();
})();
